import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const workspaceRoot = process.cwd();
const { default: StyleDictionary } = await import(
  pathToFileURL(join(workspaceRoot, 'lib', 'StyleDictionary.js')).href
);
const { outputReferencesFilter } = await import(
  pathToFileURL(join(workspaceRoot, 'lib', 'utils', 'references', 'outputReferencesFilter.js'))
    .href
);

const WARNING_PHRASE = 'filtered out token references were found';

const keepKeptOnly = (token) => token.path[0] === 'kept';

const mentionsFilteredRefWarning = (consoleOutput) =>
  consoleOutput.toLowerCase().includes(WARNING_PHRASE);

async function buildAndCapture({ tokens, fileOptions, verbosity, filter, buildPath, destination }) {
  const captured = [];
  const originals = { log: console.log, warn: console.warn, error: console.error };
  const capture = (...args) => captured.push(args.map((arg) => String(arg)).join(' '));
  console.log = capture;
  console.warn = capture;
  console.error = capture;
  try {
    const sd = new StyleDictionary({
      ...(verbosity ? { log: { verbosity } } : {}),
      tokens,
      platforms: {
        css: {
          buildPath,
          files: [
            {
              destination,
              format: 'css/variables',
              filter,
              options: fileOptions,
            },
          ],
        },
      },
    });
    await sd.buildAllPlatforms();
  } finally {
    console.log = originals.log;
    console.warn = originals.warn;
    console.error = originals.error;
  }
  const consoleOutput = captured.join('\n');
  const content = readFileSync(join(buildPath, destination), 'utf8');
  return { consoleOutput, content };
}

// Kept tokens reference excluded tokens which themselves reference further
// excluded tokens: while ordering for reference-safety the sort scans the
// filtered-out referenced tokens too, recording warnings for their refs.
const sortRecursionTokens = {
  excluded: {
    base1: { value: '#aaaaaa', type: 'other' },
    base2: { value: '#bbbbbb', type: 'other' },
    mid1: { value: '{excluded.base1}', type: 'other' },
    mid2: { value: '{excluded.base2}', type: 'other' },
  },
  kept: {
    alpha: { value: '{excluded.mid1}', type: 'other' },
    beta: { value: '{excluded.mid2}', type: 'other' },
  },
};

// A single kept token whose original value references two excluded tokens:
// outputReferencesFilter suppresses all of its refs, but a leftover warning
// for the second excluded ref remains in the global message collector.
const multiRefTokens = {
  excluded: {
    one: { value: '#111111', type: 'other' },
    two: { value: '#222222', type: 'other' },
  },
  kept: {
    combo: { value: '{excluded.one} + {excluded.two}', type: 'other' },
  },
};

test('filter + outputReferencesFilter build does not report filtered-out references when the sort scans excluded tokens (default verbosity)', async () => {
  const { consoleOutput, content } = await buildAndCapture({
    tokens: sortRecursionTokens,
    fileOptions: { outputReferences: outputReferencesFilter },
    filter: keepKeptOnly,
    buildPath: 'build-test-01/',
    destination: 'sort-recursion.css',
  });

  assert.ok(
    !mentionsFilteredRefWarning(consoleOutput),
    `expected no "filtered out token references" warning, but console printed:\n${consoleOutput}`,
  );
  assert.ok(
    content.includes('--alpha: #aaaaaa;'),
    `expected alpha emitted as a fully resolved literal, got:\n${content}`,
  );
  assert.ok(
    content.includes('--beta: #bbbbbb;'),
    `expected beta emitted as a fully resolved literal, got:\n${content}`,
  );
});

test('filter + outputReferencesFilter build does not report filtered-out references when one kept token references multiple excluded tokens (default verbosity)', async () => {
  const { consoleOutput, content } = await buildAndCapture({
    tokens: multiRefTokens,
    fileOptions: { outputReferences: outputReferencesFilter },
    filter: keepKeptOnly,
    buildPath: 'build-test-01/',
    destination: 'multi-ref.css',
  });

  assert.ok(
    !mentionsFilteredRefWarning(consoleOutput),
    `expected no "filtered out token references" warning, but console printed:\n${consoleOutput}`,
  );
  assert.ok(
    content.includes('--combo: #111111 + #222222;'),
    `expected combo emitted as a fully resolved literal, got:\n${content}`,
  );
