// kept top -> kept mid -> excluded leafA + excluded leafB
const multiExcludedChainTokens = {
  excluded: {
    leafA: { value: '#a1a1a1', type: 'other' },
    leafB: { value: '#b2b2b2', type: 'other' },
  },
  kept: {
    mid: { value: '{excluded.leafA} + {excluded.leafB}', type: 'other' },
    top: { value: '{kept.mid}', type: 'other' },
  },
};

// kept outer -> kept inner -> excluded solo (chain ends at one excluded token)
const singleExcludedChainTokens = {
  excluded: {
    solo: { value: '#0f0f0f', type: 'other' },
  },
  kept: {
    inner: { value: '{excluded.solo}', type: 'other' },
    outer: { value: '{kept.inner}', type: 'other' },
  },
};

test('no filtered-references warning when the excluded token sits at the end of a multi-level chain (kept -> kept -> excluded)', async () => {
  const { consoleOutput, content } = await buildAndCapture({
    tokens: multiExcludedChainTokens,
    fileOptions: { outputReferences: outputReferencesFilter },
    filter: keepKeptOnly,
    buildPath: 'build-test-04/',
    destination: 'chain.css',
  });

  assert.ok(
    !mentionsFilteredRefWarning(consoleOutput),
    `expected no "filtered out token references" warning for a chain ending in excluded tokens, but console printed:\n${consoleOutput}`,
  );
  assert.ok(
    content.includes('--mid: #a1a1a1 + #b2b2b2;'),
    `expected the chain's kept middle token to be a fully resolved literal, got:\n${content}`,
  );
  assert.ok(
    content.includes('--top: var(--mid);'),
    `expected the kept top token to reference the kept middle token, got:\n${content}`,
  );
  assert.ok(
    !content.includes('var(--leaf'),
    `expected no var() pointing at the excluded chain-end tokens, got:\n${content}`,
  );
  assert.ok(
    content.indexOf('--mid:') !== -1 &&
      content.indexOf('--top:') !== -1 &&
      content.indexOf('--mid:') < content.indexOf('--top:'),
    `expected the kept middle token to be declared before the token that references it, got:\n${content}`,
  );
});

