// Declaration order is deliberately worst-case (the referencing token is
// defined first): with outputReferencesFilter the emitted file must still be
// reference-safe ordered, and mid's reference to the excluded pad token must
// still be suppressed into a literal.
const orderTokens = {
  kept: {
    top: { value: '{kept.mid}', type: 'other' },
    mid: { value: '{kept.base}-{excluded.pad}', type: 'other' },
    base: { value: '#0c0c0c', type: 'other' },
  },
  excluded: {
    pad: { value: '#dadada', type: 'other' },
  },
};

test('outputReferencesFilter keeps emitted tokens reference-safe ordered: declared before use', async () => {
  const { consoleOutput, content } = await buildAndCapture({
    tokens: orderTokens,
    fileOptions: { outputReferences: outputReferencesFilter },
    filter: keepKeptOnly,
    buildPath: 'build-test-06/',
    destination: 'ordered.css',
  });

  const baseIndex = content.indexOf('--base:');
  const midIndex = content.indexOf('--mid:');
  const topIndex = content.indexOf('--top:');

  assert.ok(baseIndex !== -1, `expected --base to be emitted, got:\n${content}`);
  assert.ok(midIndex !== -1, `expected --mid to be emitted, got:\n${content}`);
  assert.ok(topIndex !== -1, `expected --top to be emitted, got:\n${content}`);

  assert.ok(
    baseIndex < midIndex && midIndex < topIndex,
    `expected declaration order --base, --mid, --top so each token is declared before the token that references it, got:\n${content}`,
  );

  assert.ok(
    content.includes('--top: var(--mid);'),
    `expected top to keep its reference to the kept mid token, got:\n${content}`,
  );
  assert.ok(
    content.includes('--mid: #0c0c0c-#dadada;'),
    `expected mid to be emitted as a fully resolved literal since its pad reference was filtered out, got:\n${content}`,
  );
  assert.ok(
    !content.includes('var(--pad'),
    `expected no var() pointing at the excluded pad token, got:\n${content}`,
  );
